SELECT
    MIN( `id` ) AS min_id,
    MAX( `id` ) AS max_id
FROM `hydra_task_instances`
WHERE
`run_status` IN

    #{runStatus}


  AND (
    `expect_time` IS NULL
     OR `expect_time`  <=  #{targetTime}
  )

    AND `actually_priority` = #{actuallyPriority}

AND (
    schedule_type IN ( 'Cycle', 'Temporary' )
    OR COALESCE( retry_cnt, 0 )  >  0
)

SELECT
    `id`,

FROM `hydra_task_instances`
WHERE `id`  >=  #{idMin}
  AND `id`  <=  #{idMax}
  AND `run_status` IN

    #{runStatus}

  AND (
      `expect_time` IS NULL
      OR `expect_time`  <=  #{targetTime}
  )

    AND `actually_priority` = #{actuallyPriority}

AND (
    schedule_type IN ( 'Cycle', 'Temporary' )
    OR COALESCE( retry_cnt, 0 )  >  0
)
ORDER BY actually_priority DESC, id ASC

SELECT MIN( `id` ) AS min_id, MAX( `id` ) AS max_id FROM `hydra_task_instances` WHERE `run_status` IN
#{runStatus}
AND COALESCE( `dry_run`, 0 ) = 0 AND COALESCE( `retry_cnt`, 0 ) < COALESCE( `retry_times`, 0 ) AND ( `expect_time` IS NULL OR `expect_time` <= #{targetTime} )

SELECT
    `id`,

FROM `hydra_task_instances`
WHERE `id`  >=  #{idMin}
  AND `id`  <=  #{idMax}
  AND `run_status` IN

    #{runStatus}

  AND COALESCE( `dry_run`, 0 ) = 0
  AND COALESCE( `retry_cnt`, 0 )  <  COALESCE( `retry_times`, 0 )
  AND (
      `expect_time` IS NULL
      OR `expect_time`  <=  #{targetTime}
  )
ORDER BY actually_priority DESC, id ASC
